    {
      "name": "Project Card — Sage Variant",
      "role": "Category tile for 'upcoming' or 'monitoring' projects",
      "description": "Background #d3e5e9 (pale sage), 1px hairline border #333333, 8px radius, padding 24px. Status label in uppercase Nng 12px weight 500 (e.g., 'COMING MONTHLY') in #3a4444. Project title in Nng 22px weight 500, color #151515. Tag pills inline at the bottom."
